import { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { PropTypes } from 'prop-types';

const Reviews = () => {
    const { movieId } = useParams();
    const [reviews, setReviews] = useState([]);
    const [error, setError] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchReviews = async () => {
            const API_KEY = 'b3fe8ad645f337f3fa9ceb8e5b164aa5'; // Mută în variabile de mediu pentru securitate
            const url = `https://api.themoviedb.org/3/movie/${movieId}/reviews?language=en-US&api_key=${API_KEY}`;

            try {
                const response = await axios.get(url);
                setReviews(response.data.results || []);
                setError(false);
            } catch (error) {
                console.error('Error fetching reviews:', error);
                setError(true);
            } finally {
                setLoading(false);
            }
        };

        fetchReviews();
    }, [movieId]);

    if (loading) {
        return <div>Loading reviews...</div>;
    }

    if (error) {
        return <div>Error loading reviews. Please try again later.</div>;
    }

    if (reviews.length === 0) {
        return <div>No reviews available for this movie.</div>;
    }

    return (
        <div>
            <h1>Reviews</h1>
            <ul>
                {reviews.map(rev => (
                    <li key={rev.id}>
                        <h3>Author: {rev.author || 'Anonymous'}</h3>
                        <p>{rev.content || 'No content available.'}</p>
                    </li>
                ))}
            </ul>
        </div>
    );
};

Reviews.propTypes = {
    reviews: PropTypes.arrayOf(
        PropTypes.shape({
            id: PropTypes.string.isRequired,
            author: PropTypes.string,
            content: PropTypes.string,
        })
    ),
};

export default Reviews;
